-- teams of p_user from supabase.hook.teams; execute is supabase_auth_admin only
create or replace function "permdock"."member_team_ids_for"(p_user uuid, p_active text default null)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select t."team_id"
  from "public"."team_members" t
  where t."user_id" = p_user

  order by (p_active is not null and t."organization_id"::text is not distinct from p_active) desc, t."team_id"
$$;
revoke execute on function "permdock"."member_team_ids_for"(uuid, text) from public, anon, authenticated;
grant execute on function "permdock"."member_team_ids_for"(uuid, text) to supabase_auth_admin;

-- the caller's teams only, for better-supabase's teamIdsOf
create or replace function "permdock"."member_team_ids_of"(p_user uuid)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m.id
  from "permdock"."member_team_ids_for"(p_user, null) as m(id)
  where p_user = (select "permdock".permdock_user_id())
$$;
revoke execute on function "permdock"."member_team_ids_of"(uuid) from public, anon;
grant execute on function "permdock"."member_team_ids_of"(uuid) to authenticated;

-- the helpers for a user the caller names: trusted SQL acting for a stored user; no client role may execute them
create or replace function "permdock".permdock_has_for(p_user uuid, p_grant text)
returns boolean
language sql
stable
security definer
cost 1000
set search_path = ''
as $$
  select exists (
    select 1
    from "permdock".user_roles ur
    join "permdock".role_permissions rp on rp.role = ur.role::text
    where ur.user_id = p_user
      and rp.grant_key = p_grant
      and rp.scope = 'global'
  )
$$;
revoke execute on function "permdock".permdock_has_for(uuid, text) from public, anon, authenticated;

